Color pigment(const std::string& hex){unsigned n=unsigned(std::stoul(hex.substr(1),nullptr,16));return {static_cast<unsigned char>(n>>16),static_cast<unsigned char>(n>>8),static_cast<unsigned char>(n),255};}
Color blendPreview(Color a,Color b,float t){t=std::clamp(t,0.f,1.f);return {static_cast<unsigned char>(a.r*(1-t)+b.r*t),static_cast<unsigned char>(a.g*(1-t)+b.g*t),static_cast<unsigned char>(a.b*(1-t)+b.b*t),255};}
Color batchPigment(const CulinaryBatch& batch){double red=0,greenValue=0,blue=0,total=0,massTotal=0,brown=0;for(auto& part:batch.parts){double shadeMass=foodMass(part.food);massTotal+=shadeMass;brown+=(part.food.brown*.45+part.food.scorch*.25)*shadeMass;for(auto& [key,grams]:part.food.ingredients){auto c=pigment(ingredient(key).color);red+=c.r*grams;greenValue+=c.g*grams;blue+=c.b*grams;total+=grams;}}if(total<=0)return Color{130,153,154,255};Color mixture={static_cast<unsigned char>(red/total),static_cast<unsigned char>(greenValue/total),static_cast<unsigned char>(blue/total),255};return blendPreview(mixture,Color{93,53,34,255},float(std::clamp(brown/std::max(.001,massTotal),0.,.62)));}
std::string lower(std::string s){for(auto& c:s)c=char(std::tolower(static_cast<unsigned char>(c)));return s;}
void panel(Rectangle r){DrawRectangleRounded(r,.025f,6,white);DrawRectangleLinesEx(r,1,line);}
void scrollBar(Rectangle body,float total,float offset){if(total<=body.height)return;float thumb=body.height*body.height/total;DrawRectangleRec({body.x+body.width+4,body.y,2,body.height},paper);DrawRectangleRec({body.x+body.width+4,body.y+(body.height-thumb)*offset/(total-body.height),2,thumb},muted);}
bool dosing(const Machine* m){return m&&(m->kind==MachineKind::Feeder||isDosingMachine(m->kind));}
bool cropSource(const Machine* m){return m&&(m->kind==MachineKind::SeedHopper||isFarmBed(m->kind));}
std::string directionName(int d){static const std::array<std::string,4> names={"E","S","W","N"};return names[size_t((d%4+4)%4)];}
std::string sensorReading(MachineKind kind,double value){if(kind==MachineKind::PHProbe)return "pH "+roundTo(value,2);if(kind==MachineKind::TemperatureLogger)return roundTo(value,1)+" C";if(kind==MachineKind::DropletViewer)return roundTo(value,1)+" um";return roundTo(value,2)+" aroma units";}
